import pathlib,json,hashlib,collections
R=pathlib.Path(__file__).resolve().parents[2];D=R/'data/language-mixture-v3';p=json.loads((D/'profile.json').read_text());assert hashlib.sha256((D/'sample.jsonl').read_bytes()).hexdigest()==p['sample_sha256']
rows=[json.loads(l) for l in (D/'sample.jsonl').read_text().splitlines()]
review={5:'Coherent activities but unqualified fixed learning-style framing; not externally verified.',7:'Historical dated emissions claim and atom/molecule wording confusion; broken quotation.',10:'Unlabeled glossary fragments, missing animation and oversimplified treatment claims; not fact-checked.',11:'Readable conceptual explanation, but repeated conflation of shortest path/geodesic and space/spacetime warrants technical review.',13:'Missing diagrams and clockwise quadrant order contradicts subsequent described sign sequence.',15:'Long unlabeled glossary tail and inconsistent stated incubation timing; geographic labels and treatment assertions warrant verification.'}
