(D/'judgments.json').write_text(json.dumps(out,indent=2)+'\n')
summary=dict(state='review_complete_not_admitted',training_admitted=False,ratings=dict(collections.Counter(x['rating'] for x in out)),score4_after_filters_tokens=809031,score4_after_all_sample_deferrals_tokens=809031-sum(x['tokens'] for x in out if x['rating']!='retain'),factual_verification='None; suspected issues and internal inconsistencies only.',profile_sha256=hashlib.sha256((D/'profile.json').read_bytes()).hexdigest(),judgments_sha256=hashlib.sha256((D/'judgments.json').read_bytes()).hexdigest())
(D/'review.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary,indent=2))
